#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    vector<long long> dist(n + 1, 0);
    bool negative = false;
    for (long long round = 0; round < n; round++) {
        bool changed = false;
        for (const vector<long long>& e : edges) {
            if (dist[e[0]] + e[2] < dist[e[1]]) {
                dist[e[1]] = dist[e[0]] + e[2];
                changed = true;
            }
        }
        if (!changed) break;
        if (round == n - 1) negative = true;
    }
    cout << (negative ? "yes" : "no") << "\n";

    return 0;
}

